1	export type Customer = {
2	  yearsWithMHPCO: number;
3	  previousContracts: number;
4	};
5	
6	export type Item = {
7	  type: string;
8	  material?: string;
9	  enchantment?: number;
10	  cursed?: boolean;
11	};
12	
13	const PROCESSING_FEE = 5;
14	
15	const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
16	  sword: 100,
17	  amulet: 60,
18	  staff: 80,
19	  potion: 40,
20	  rune: 25,
21	  moonstone: 25,
22	};
23	
24	const CURSED_SURCHARGE_RATE = 0.5;
25	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
26	const HIGH_ENCHANTMENT_THRESHOLD = 5;
27	
28	const basePremiumOf = (item: Item): number =>
29	  BASE_PREMIUM_BY_ITEM_TYPE[item.type];
30	
31	const itemModifierRateOf = (item: Item): number =>
32	  (item.cursed ? CURSED_SURCHARGE_RATE : 0) +
33	  ((item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD
34	    ? HIGH_ENCHANTMENT_SURCHARGE_RATE
35	    : 0);
36	
37	const premiumOf = (item: Item): number =>
38	  basePremiumOf(item) * (1 + itemModifierRateOf(item));
39	
40	const sumItemPremiums = (items: Item[]): number =>
41	  items.reduce((sum, item) => sum + premiumOf(item), 0);
42	
43	// Policy-level modifiers are whole percentages of the policy base premium.
44	// Applying them as `amount * percent / 100` keeps the arithmetic exact:
45	// `100 * 110 / 100` is 110, whereas `100 * 1.1` is 110.00000000000001.
46	const applyPercentage = (amount: number, percent: number): number =>
47	  (amount * percent) / 100;
48	
49	const FULL_PERCENTAGE = 100;
50	const FIRST_INSURANCE_SURCHARGE_PERCENTAGE = 10;
51	const LOYALTY_DISCOUNT_PERCENTAGE = 20;
52	const LOYALTY_YEARS_THRESHOLD = 2;
53	
54	const loyaltyDiscountPercentageOf = (customer: Customer): number =>
55	  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD
56	    ? LOYALTY_DISCOUNT_PERCENTAGE
57	    : 0;
58	
59	const FOLLOW_UP_DISCOUNT_PERCENTAGE = 15;
60	const FOLLOW_UP_CONTRACTS_THRESHOLD = 1;
61	
62	const followUpDiscountPercentageOf = (customer: Customer): number =>
63	  customer.previousContracts >= FOLLOW_UP_CONTRACTS_THRESHOLD
64	    ? FOLLOW_UP_DISCOUNT_PERCENTAGE
65	    : 0;
66	
67	const policyPercentageOf = (customer: Customer): number =>
68	  FULL_PERCENTAGE +
69	  FIRST_INSURANCE_SURCHARGE_PERCENTAGE -
70	  loyaltyDiscountPercentageOf(customer) -
71	  followUpDiscountPercentageOf(customer);
72	
73	const BLOCK_SIZE = 3;
74	const BLOCK_BASE_PREMIUM = 60;
75	
76	const isComponentBlock = (sameTypeGroup: Item[]): boolean =>
77	  sameTypeGroup.length === BLOCK_SIZE;
78	
79	const groupByType = (items: Item[]): Item[][] => {
80	  const groups = new Map<string, Item[]>();
81	  for (const item of items) {
82	    const group = groups.get(item.type) ?? [];
83	    group.push(item);
84	    groups.set(item.type, group);
85	  }
86	  return [...groups.values()];
87	};
88	
89	const premiumOfGroup = (sameTypeGroup: Item[]): number =>
90	  isComponentBlock(sameTypeGroup)
91	    ? BLOCK_BASE_PREMIUM
92	    : sumItemPremiums(sameTypeGroup);
93	
94	export const quote = (customer: Customer, items: Item[]): number => {
95	  const policyPremium = groupByType(items).reduce(
96	    (sum, group) => sum + premiumOfGroup(group),
97	    0,
98	  );
99	
100	  const withPolicyModifiers = applyPercentage(
101	    policyPremium,
102	    policyPercentageOf(customer),
103	  );
104	
105	  return withPolicyModifiers + PROCESSING_FEE;
106	};
107	
108	export const claim = (): number => {
109	  return undefined as unknown as number;
110	};
